import {createNativeStackNavigator} from '@react-navigation/native-stack';
import NavigationName from '../constants/NavigationName';
import Toast from 'react-native-toast-message';
import {PaperProvider} from 'react-native-paper';
import {ApplicationProvider, IconRegistry} from '@ui-kitten/components';
import * as eva from '@eva-design/eva';
import {EvaIconsPack} from '@ui-kitten/eva-icons';
import {default as theme} from '../../custom-theme.json'; // <-- Import app theme
import {default as mapping} from '../../mapping.json'; // <-- Import app mapping

import {useAppDispatch, useAppSelector} from '../hooks/useRedux';
import {Fragment, useEffect, useState} from 'react';

import {useTranslation} from 'react-i18next';
import React from 'react';
import {ActivityIndicator, View} from 'react-native';
import {Color} from '../constants';
import toastConfig from '../utils/ToastConfig';
import {useZutandStore} from '../zutand/store';
import {ServiceIdApp} from '../model/enum/common.enum';
import {useAccountSettingService} from '../hooks/apiHooks/useAccountInfoServices';
import NoAuthComponent from '../app/components/NoAuth';
import DetailReceiptScreen from '../app/screen/detail-receipt';
import RecieptInfo from '../app/screen/detail-receipt/component/reciept-info';
import TransferReceipt from '../app/screen/detail-receipt/component/relate-receipt';
import Attachments from '../app/screen/detail-receipt/component/detail-attachments';
import WithComponent from '../app/components/withComponent';
import CreateTicketScreen from '../app/screen/create-new/components/create-ticket';
import ViewDocumentScreen from '../app/screen/detail-receipt/component/detail-attachments/component/view-document';
import WebViewScreen from '../app/components/ViewWebview';
import {commonActions} from '../redux/slices';
import {useTicketServices} from '../hooks/apiHooks/useAPI';
import BottomTabNavigationEBLDT from './BottomTabEBLDT';
const Stack = createNativeStackNavigator();
const EBLDTNavigation = (props: any) => {
  const AccountSettingServices = useAccountSettingService();
  const {i18n} = useTranslation();
  const [isLoadInitData, setIsLoadInitData] = useState(true);
  const dispatch = useAppDispatch();
  const {language} = useAppSelector(state => state.common);
  const {setListMenuViewBLDT} = useZutandStore();
  const ListServices = useTicketServices();
  const fetchListMenuViewBLDT = async () => {
    // const data = await ListServices.login();
    // dispatch(commonActions.setAccessToken(data.access_token));
    const listMenuViewBLDT = await AccountSettingServices.getMenuView(
      ServiceIdApp.EBLDT,
    );
    setListMenuViewBLDT(listMenuViewBLDT);
  };

  useEffect(() => {
    fetchListMenuViewBLDT();
    i18n.changeLanguage(language);
    setIsLoadInitData(false);
  }, []);

  if (isLoadInitData) {
    return (
      <View
        style={{
          flex: 1,
          justifyContent: 'center',
          alignItems: 'center',
        }}>
        <ActivityIndicator size={'large'} color={Color.BgPrimary} />
      </View>
    );
  }

  return (
    <Fragment>
      <IconRegistry icons={[EvaIconsPack]} />
      <ApplicationProvider
        customMapping={mapping as any}
        {...eva}
        theme={{...eva.light, ...theme}}>
        <PaperProvider>
          <Stack.Navigator
            screenOptions={{
              headerShown: false,
            }}>
            <Stack.Screen
              name={NavigationName.BottomTabsBLDT}
              component={BottomTabNavigationEBLDT}
            />
            <Stack.Screen
              name={NavigationName.CreateTicketScreen}
              component={CreateTicketScreen}
            />
            <Stack.Screen
              name={NavigationName.DetailReceiptScreen}
              component={DetailReceiptScreen}
            />
            <Stack.Screen
              name={NavigationName.RecieptInfo}
              component={RecieptInfo}
            />
            <Stack.Screen
              name={NavigationName.TransferReceipt}
              component={TransferReceipt}
            />
            <Stack.Screen
              name={NavigationName.Attachments}
              component={Attachments}
            />
            <Stack.Screen
              name={NavigationName.ViewDocumentScreen}
              component={ViewDocumentScreen}
            />
            <Stack.Screen
              name={NavigationName.WebViewScreen}
              component={WebViewScreen}
            />

            {/* <Stack.Screen
              name="TicketDetailERequest"
              component={WithComponent}
            /> */}
          </Stack.Navigator>
          <Toast config={toastConfig} />
        </PaperProvider>
      </ApplicationProvider>
    </Fragment>
  );
};

export default EBLDTNavigation;
